CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_colaboradores_completo` AS select `c`.`id` AS `id`,`c`.`campana_id` AS `campana_id`,`c`.`nombres` AS `nombres`,`c`.`apellidos` AS `apellidos`,`c`.`tipo_documento` AS `tipo_documento`,`c`.`documento` AS `documento`,`c`.`fecha_nacimiento` AS `fecha_nacimiento`,`c`.`genero` AS `genero`,`c`.`perfil` AS `perfil`,`c`.`nivel_liderazgo` AS `nivel_liderazgo`,`c`.`nivel_participacion` AS `nivel_participacion`,`c`.`areas_interes` AS `areas_interes`,`c`.`dato_potencial` AS `dato_potencial`,`c`.`dato_historico` AS `dato_historico`,`c`.`estado` AS `estado`,`c`.`revision` AS `revision`,`c`.`departamento` AS `departamento`,`c`.`municipio` AS `municipio`,`c`.`tipo_territorio` AS `tipo_territorio`,`c`.`territorio` AS `territorio`,`c`.`barrio` AS `barrio`,`c`.`direccion` AS `direccion`,`c`.`detalle_ubicacion` AS `detalle_ubicacion`,`c`.`lider_directo` AS `lider_directo`,`c`.`email` AS `email`,`c`.`telefono` AS `telefono`,`c`.`telefono_whatsapp` AS `telefono_whatsapp`,`c`.`observaciones` AS `observaciones`,`c`.`usuario_registro_id` AS `usuario_registro_id`,`c`.`created_at` AS `created_at`,`c`.`updated_at` AS `updated_at`,`c`.`puesto_votacion` AS `puesto_votacion`,`c`.`mesa_votacion` AS `mesa_votacion`,concat(`c`.`nombres`,' ',`c`.`apellidos`) AS `nombre_completo`,timestampdiff(YEAR,`c`.`fecha_nacimiento`,curdate()) AS `edad`,concat(`l`.`nombres`,' ',`l`.`apellidos`) AS `nombre_lider`,`l`.`documento` AS `documento_lider_completo`,count(distinct `s`.`id`) AS `total_seguidores` from ((`colaboradores` `c` left join `colaboradores` `l` on(`c`.`lider_directo` = `l`.`documento`)) left join `colaboradores` `s` on(`s`.`lider_directo` = `c`.`documento`)) group by `c`.`id`